// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {GameErrors as E} from "./libraries/GameErrors.sol";

import {GameTypes as G} from "./libraries/GameTypes.sol";
import {GameConfig} from "./GameConfig.sol";

/// @notice Caller-scoped clans and season/week counters; canonical caller is Villages.
/// @dev Clan Hall levels and member caps come from GameConfig.
contract Clans {
    uint256 public immutable seasonStartedAt;
    uint256 public constant UNIT = 1_000_000;
    GameConfig public immutable config;

    struct Clan {
        string name;
        address founder;
        uint8 capacity;
        address[] members;
    }

    struct Counters {
        uint256 build;
        uint256 research;
        uint256 attack;
        uint256 defense;
        uint256 loot;
    }

    struct World {
        uint256 nextClan;
        mapping(uint256 => Clan) clans;
        mapping(address => uint256) membership;
        mapping(bytes32 => bool) names;
        mapping(address => Counters) season;
        mapping(uint256 => mapping(address => Counters)) weeklyCounters;
        mapping(uint256 => mapping(address => bool)) invited;
    }
    mapping(address => World) private worlds;
    event ClanFounded(address indexed game, uint256 indexed clanId, address indexed founder, string name);
    event Joined(address indexed game, uint256 indexed clanId, address indexed player);
    event Invited(address indexed game, uint256 indexed clanId, address indexed player, bool open);
    event Left(address indexed game, uint256 indexed clanId, address indexed player);
    event CapacityRaised(address indexed game, uint256 indexed clanId, uint256 capacity);
    event Ranked(
        address indexed game, address indexed player, uint256 indexed week, uint8 category, uint256 amount
    );

    constructor(GameConfig config_) {
        require(address(config_) != address(0), E.InvalidDependency());
        config = config_;
        seasonStartedAt = block.timestamp;
    }

    function _cap(GameConfig.Social memory s, uint8 hall) private pure returns (uint8) {
        return uint8(G.min(s.maxMembers, uint256(hall) * s.capPerHall));
    }

    function week() public view returns (uint256) {
        return (block.timestamp - seasonStartedAt) / 7 days;
    }

    function clanOf(address game, address player) external view returns (uint256) {
        return worlds[game].membership[player];
    }

    function sameClan(address game, address a, address b) public view returns (bool) {
        uint256 id = worlds[game].membership[a];
        return id != 0 && id == worlds[game].membership[b];
    }

    function invited(address game, uint256 id, address player) external view returns (bool) {
        return worlds[game].invited[id][player];
    }

    function clan(address game, uint256 id) external view returns (Clan memory) {
        return worlds[game].clans[id];
    }

    function counters(address game, address player, bool weekly, uint256 week_)
        external
        view
        returns (Counters memory)
    {
        return weekly ? worlds[game].weeklyCounters[week_][player] : worlds[game].season[player];
    }

    function overall(address game, address player, bool weekly, uint256 week_)
        external
        view
        returns (uint256)
    {
        Counters storage c = weekly ? worlds[game].weeklyCounters[week_][player] : worlds[game].season[player];
        uint256 build = c.build / (100 * UNIT);
        return build + c.research / (100 * UNIT) + G.min(build, (c.attack + c.defense) / 200);
    }

    function found(address player, string calldata name, uint8 hall) external returns (uint256 id) {
        GameConfig.Social memory s = config.social();
        require(hall >= s.foundHall, E.ClanHall3Required());
        World storage w = worlds[msg.sender];
        require(w.membership[player] == 0 && player != address(0), E.AlreadyInClan());
        bytes32 key = G.nameKey(name, 24);
        require(!w.names[key], E.ClanNameTaken());
        w.names[key] = true;
        id = ++w.nextClan;
        Clan storage c = w.clans[id];
        c.name = name;
        c.founder = player;
        c.capacity = _cap(s, hall);
        c.members.push(player);
        w.membership[player] = id;
        emit ClanFounded(msg.sender, id, player, name);
    }

    function join(address player, uint256 id, uint8 hall) external {
        World storage w = worlds[msg.sender];
        Clan storage c = w.clans[id];
        require(hall >= config.social().joinHall && player != address(0) && w.membership[player] == 0, E.CannotJoin());
        require(c.founder != address(0) && c.members.length < c.capacity, E.ClanFullOrMissing());
        require(w.invited[id][player], E.NotInvited());
        delete w.invited[id][player];
        w.membership[player] = id;
        c.members.push(player);
        emit Joined(msg.sender, id, player);
    }

    /// @notice Only the founder admits members; an invitation is consumed by joining.
    function invite(address founder, address player, bool open) external {
        World storage w = worlds[msg.sender];
        uint256 id = w.membership[founder];
        require(id != 0 && w.clans[id].founder == founder && player != address(0), E.OnlyFounderInvites());
        w.invited[id][player] = open;
        emit Invited(msg.sender, id, player, open);
    }

    function leave(address player) external {
        World storage w = worlds[msg.sender];
        uint256 id = w.membership[player];
        Clan storage c = w.clans[id];
        require(id != 0, E.NotInClan());
        require(c.founder != player || c.members.length == 1, E.FounderLeavesLast());
        for (uint256 i; i < c.members.length; ++i) {
            if (c.members[i] == player) {
                c.members[i] = c.members[c.members.length - 1];
                c.members.pop();
                break;
            }
        }
        delete w.membership[player];
        if (c.members.length == 0) c.founder = address(0);
        emit Left(msg.sender, id, player);
    }

    function raiseCapacity(address player, uint8 hall) external {
        World storage w = worlds[msg.sender];
        uint256 id = w.membership[player];
        Clan storage c = w.clans[id];
        uint8 cap = _cap(config.social(), hall);
        require(id != 0 && c.founder == player && cap > c.capacity, E.CannotRaiseCapacity());
        c.capacity = cap;
        emit CapacityRaised(msg.sender, id, c.capacity);
    }

    function record(address player, uint8 kind, uint256 amount) external {
        require(kind < 5, E.InvalidCounter());
        _add(worlds[msg.sender].season[player], kind, amount);
        uint256 week_ = week();
        _add(worlds[msg.sender].weeklyCounters[week_][player], kind, amount);
        emit Ranked(msg.sender, player, week_, kind, amount);
    }

    function _add(Counters storage c, uint8 kind, uint256 amount) private {
        if (kind == 0) c.build += amount;
        else if (kind == 1) c.research += amount;
        else if (kind == 2) c.attack += amount;
        else if (kind == 3) c.defense += amount;
        else c.loot += amount;
    }
}

GameConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {GameErrors as E} from "./libraries/GameErrors.sol";
import {GameTypes as G} from "./libraries/GameTypes.sol";

/// @notice Every number of the Squeek Wars economy, in one owner-editable table.
/// @dev The other contracts read it live, so a change applies from the next action on; villages,
/// armies and counters stay where they are. Percentages are whole percent unless named Milli.
/// Resource and SEED amounts in setters are whole units unless the field says Unit (millionths).
contract GameConfig {
    uint256 public constant UNIT = 1_000_000;
    uint256 public constant MAX_TIERS = 8;
    uint256 public constant MAX_TROOPS = 1_000_000;
    uint256 public constant NFT_COUNT_PRECISION = 32;

    address public owner;
    uint256 public version; // +1 on every change, so readers can cache the table

    struct Economy {
        uint32 startResources; // each resource at founding
        uint32 startSeed;
        uint32 shieldHours; // beginner shield
        uint32 fieldRate; // per hour at level 1
        uint16 fieldRateGrowth; // ×1/100 per level
        uint16 fieldCostGrowth;
        uint32 fieldSeconds; // level-1 build time
        uint16 fieldTimeGrowth;
        uint8 fieldMaxLevel;
        uint8 thBuildCutPct; // build time −% per Town Hall level above 1
        uint8 plotsBase; // plots = base + Town Hall level, at most plotsMax
        uint8 plotsMax;
        uint8 cancelRefundPct;
        uint16 upkeepMilli; // Food per room per hour, in thousandths
        uint16 barracksTimePct; // training time × this % per Barracks level above 1
        uint16 marketBase; // 100 of a resource gives base + perLevel × (Market − 1)
        uint16 marketPerLevel;
        uint32 boostSeed;
        uint16 boostPct;
        uint32 boostHours;
        uint32 peaceSeed;
        uint32 peaceHours;
        uint32 peaceCooldownHours;
        uint32 bannerSeed;
        uint16 squeekBuildPct; // most build time a wallet's Squeeks can cut
        uint32 squeekWorkTarget; // a day's work that gives the full Squeek cut
        uint32 seedWorkDiv; // SEED per village = day's work ÷ this
        uint32 wheelWorkDiv; // wheel bonus = day's work ÷ this
        uint16 wheelPctPerLevel; // wheel bonus cap per Wheelhouse level
        uint32 xpWorkDiv; // champion XP per claimed day = work ÷ this …
        uint32 xpDailyCap; // … at most this
    }

    struct Storage {
        uint32 storeBase;
        uint32 storePer; // Storehouse level l adds storePer × storeGrowth^(l−1)
        uint16 storeGrowth;
        uint32 vaultBase;
        uint32 vaultPer;
        uint16 vaultGrowth;
        uint32 roomBase;
        uint32 roomPer; // Burrow level l adds roomPer × l × roomGrowth^(l−1)
        uint16 roomGrowth;
    }

    struct War {
        uint16 winRatioPct; // attack ≥ defense × this % wins outright
        uint16 lossPct; // each side loses min(1, enemy ÷ own × this %)
        uint16 scoutBonusPct;
        uint32 scoutHours;
        uint8 raidsPerDay; // per attacker and target
        uint8 weakGap; // targets this many Town Hall levels lower …
        uint16 weakLootPct; // … give this % of the loot and no points
        uint16 siegePerWall; // siege units per Walls level knocked down
        uint8 maxWallDamage;
        uint32 repairHours; // one Walls level back per this many hours
        uint16 thGuard; // flat defense per Town Hall level
        uint16 forgePct; // attack and defense % per Forge level
        uint16 wallsPct; // defense % per Walls level
        uint16 maxSupport; // clan support groups one village can host
        uint16 campDamagePct; // a lost raid removes this % of its attack from a camp's defense
    }

    struct Hero {
        uint16 mightBase;
        uint16 mightPerPoint;
        uint32 attackPerPointMilli; // bonus per point in millionths (5,000 = 0.5%)
        uint32 defensePerPointMilli;
        uint32 carryPerPointMilli;
        uint8 statCap; // points per bonus
        uint8 pointsPerLevel;
        uint8 maxLevel;
        uint32 xpPerLevel; // level = 1 + √(XP ÷ this)
        uint16 squeekPct; // a Squeek holder's XP and stats, % of normal
        uint16 killXpDiv; // XP = killed value ÷ this
    }

    struct Wild {
        uint16 defenseBase; // full defense = size × min(defenseCap, base + perDay × season day)
        uint16 defensePerDay;
        uint16 defenseCap;
        uint16 stockBase; // stock per hour = size × (base + perDay × season day)
        uint16 stockPerDay;
        uint16 stockHours; // stock cap in hours of output
        uint32 regrowHours;
        uint16[3] sizePct; // small, normal, large
        uint16 lossValueNum; // killed value = defense removed × num ÷ den
        uint16 lossValueDen;
    }

    struct Social {
        uint8 joinHall;
        uint8 foundHall;
        uint8 capPerHall;
        uint8 maxMembers;
    }

    struct Unit {
        bool enabled;
        uint8 tier; // research tier needed
        uint8 role; // 0 normal, 1 scout, 2 siege
        uint16 attack;
        uint16 defense;
        uint16 speed; // tiles per hour
        uint16 carry;
        uint16 room;
        uint32 seconds_; // training time at Barracks 1
        uint32[4] cost;
    }

    struct Building {
        bool enabled;
        uint8 maxLevel;
        uint8 thCap; // 0 none, 1 ≤ Town Hall, 2 ≤ 2 × Town Hall
        uint8 tier; // research tier needed to build
        uint8 effect; // GameTypes.FX_*, applied on top of the slot's built-in role
        uint32 effectPerLevel;
        uint16 costGrowth;
        uint16 seedGrowth;
        uint16 timeGrowth;
        uint32 seed;
        uint32 seconds_;
        uint32[4] cost;
    }

    struct Tier {
        uint64 costEachUnit; // per resource, millionths
        uint64 seedUnit;
        uint32 seconds_;
        uint8 academy;
        uint16 carryPct; // bonuses unlocked by this tier
        uint16 speedPct;
        uint8 medicinePct; // fallen units returned
    }

    Economy private econ_;
    Storage private storage_;
    War private war_;
    Hero private hero_;
    Wild private wild_;
    Social private social_;
    uint32[4][4] private fieldCost_; // [field type][resource]: forest, farm, quarry, mine
    Unit[16] private units_;
    Building[16] private buildings_;
    Tier[8] private tiers_;
    uint8 public tierCount;
    string[16] private unitNames_;
    string[16] private buildingNames_;

    event Changed(string what, uint256 index, uint256 version);
    event OwnershipTransferred(address indexed from, address indexed to);

    modifier onlyOwner() {
        if (msg.sender != owner) revert E.NotOwner();
        _;
    }

    constructor(address owner_) {
        if (owner_ == address(0)) revert E.InvalidConfig();
        owner = owner_;
        emit OwnershipTransferred(address(0), owner_);
        econ_ = Economy(750, 1500, 168, 18, 140, 160, 1440, 140, 10, 3, 3, 12, 80, 500, 90, 25, 5, 500, 25, 24, 4000, 12, 72, 1000, 30, 11000, 10, 4320, 25, 100, 150);
        storage_ = Storage(1500, 1800, 122, 300, 500, 122, 30, 20, 112);
        war_ = War(200, 50, 10, 12, 3, 3, 50, 20, 2, 12, 40, 2, 4, 30, 50);
        hero_ = Hero(50, 25, 5000, 5000, 10000, 20, 4, 30, 100, 110, 20);
        wild_ = Wild(150, 40, 4000, 20, 2, 24, 24, [uint16(60), 100, 150], 204, 56);
        social_ = Social(1, 3, 3, 30);
        fieldCost_ = [[uint32(30), 50, 45, 40], [uint32(45), 20, 50, 45], [uint32(45), 45, 20, 50], [uint32(50), 45, 45, 10]];
        _unit(0, "Spearman", 0, 0, 40, 35, 6, 50, 1, 900, [uint32(50), 45, 45, 40]);
        _unit(1, "Forager", 1, 0, 20, 15, 8, 120, 1, 720, [uint32(55), 55, 30, 20]);
        _unit(2, "Shieldbearer", 2, 0, 15, 70, 5, 20, 1, 1080, [uint32(60), 45, 70, 45]);
        _unit(3, "Berserker", 2, 0, 75, 20, 6, 40, 1, 1200, [uint32(55), 55, 35, 100]);
        _unit(4, "Charger", 3, 0, 90, 50, 14, 80, 2, 2100, [uint32(120), 130, 90, 170]);
        _unit(5, "Catapult", 4, G.ROLE_SIEGE, 30, 10, 3, 0, 4, 4200, [uint32(320), 140, 300, 170]);
        _unit(6, "Scout", 2, G.ROLE_SCOUT, 0, 5, 16, 0, 1, 480, [uint32(30), 40, 20, 40]);
        _building(0, "Town Hall", 10, 0, 0, 175, 667, 150, 2700, 150, [uint32(180), 170, 180, 170]);
        _building(1, "Walls", 10, 1, 0, 162, 0, 0, 2160, 145, [uint32(80), 60, 220, 140]);
        _building(2, "Wheelhouse", 10, 1, 0, 168, 300, 150, 2160, 145, [uint32(100), 110, 90, 100]);
        _building(3, "Storehouse", 20, 2, 0, 128, 0, 0, 1620, 120, [uint32(110), 100, 100, 90]);
        _building(4, "Vault", 20, 2, 1, 128, 0, 0, 1620, 120, [uint32(70), 60, 80, 50]);
        _building(5, "Burrow", 10, 1, 0, 155, 0, 0, 1800, 145, [uint32(70), 110, 70, 50]);
        _building(6, "Barracks", 10, 1, 0, 162, 0, 0, 2160, 145, [uint32(150), 150, 130, 170]);
        _building(7, "Academy", 10, 1, 0, 162, 0, 0, 2160, 145, [uint32(160), 160, 170, 210]);
        _building(8, "Forge", 10, 1, 2, 162, 0, 0, 2160, 145, [uint32(130), 110, 140, 260]);
        _building(9, "Clan Hall", 10, 1, 2, 162, 0, 0, 2160, 145, [uint32(190), 200, 180, 130]);
        _building(10, "Market", 10, 1, 0, 162, 0, 0, 2160, 145, [uint32(150), 200, 150, 150]);
        tiers_[0] = Tier(150_000_000, 300_000_000, 7200, 1, 0, 0, 0);
        tiers_[1] = Tier(330_000_000, 600_000_000, 12960, 2, 0, 0, 0);
        tiers_[2] = Tier(726_000_000, 1_200_000_000, 23328, 4, 20, 0, 0);
        tiers_[3] = Tier(1_597_200_000, 2_400_000_000, 41990, 6, 0, 0, 10);
        tiers_[4] = Tier(3_513_840_000, 4_800_000_000, 75582, 8, 20, 20, 0);
        tierCount = 5;
        version = 1;
    }

    function _unit(uint8 i, string memory name, uint8 tier, uint8 role, uint16 a, uint16 d, uint16 s, uint16 c, uint16 r, uint32 secs, uint32[4] memory cost) private {
        units_[i] = Unit(true, tier, role, a, d, s, c, r, secs, cost);
        unitNames_[i] = name;
    }

    function _building(uint8 i, string memory name, uint8 maxLevel, uint8 thCap, uint8 tier, uint16 costGrowth, uint32 seed, uint16 seedGrowth, uint32 secs, uint16 timeGrowth, uint32[4] memory cost) private {
        buildings_[i] = Building(true, maxLevel, thCap, tier, G.FX_NONE, 0, costGrowth, seedGrowth, timeGrowth, seed, secs, cost);
        buildingNames_[i] = name;
    }

    // ------------------------------------------------------------------ owner

    function transferOwnership(address to) external onlyOwner {
        if (to == address(0)) revert E.InvalidConfig();
        emit OwnershipTransferred(owner, to);
        owner = to;
    }

    function _changed(string memory what, uint256 index) private {
        emit Changed(what, index, ++version);
    }

    function setEconomy(Economy calldata e) external onlyOwner {
        require(
            e.fieldRate > 0 && e.fieldMaxLevel > 0 && e.fieldMaxLevel <= 20 && e.plotsMax <= 16
                && e.cancelRefundPct <= 100 && e.barracksTimePct > 0 && e.barracksTimePct <= 100
                && e.thBuildCutPct <= 10 && e.squeekBuildPct <= 90 && e.squeekWorkTarget > 0 && e.seedWorkDiv > 0
                && e.wheelWorkDiv > 0 && e.xpWorkDiv > 0 && e.boostHours > 0 && e.peaceHours > 0,
            E.InvalidConfig()
        );
        econ_ = e;
        _changed("economy", 0);
    }

    function setStorage(Storage calldata s) external onlyOwner {
        require(s.storeBase > 0 && s.storeGrowth >= 100 && s.vaultGrowth >= 100 && s.roomGrowth >= 100, E.InvalidConfig());
        storage_ = s;
        _changed("storage", 0);
    }

    function setWar(War calldata w) external onlyOwner {
        require(
            w.winRatioPct >= 100 && w.lossPct > 0 && w.siegePerWall > 0 && w.repairHours > 0 && w.maxSupport <= 100
                && w.campDamagePct <= 100 && w.weakLootPct <= 100,
            E.InvalidConfig()
        );
        war_ = w;
        _changed("war", 0);
    }

    function setHero(Hero calldata h) external onlyOwner {
        require(h.maxLevel > 0 && h.maxLevel <= 100 && h.xpPerLevel > 0 && h.killXpDiv > 0 && h.squeekPct >= 100, E.InvalidConfig());
        hero_ = h;
        _changed("hero", 0);
    }

    function setWild(Wild calldata w) external onlyOwner {
        require(w.lossValueDen > 0 && w.regrowHours > 0, E.InvalidConfig());
        wild_ = w;
        _changed("wild", 0);
    }

    function setSocial(Social calldata s) external onlyOwner {
        require(s.joinHall > 0 && s.foundHall >= s.joinHall && s.maxMembers > 0, E.InvalidConfig());
        social_ = s;
        _changed("social", 0);
    }

    function setFieldCosts(uint32[4][4] calldata c) external onlyOwner {
        fieldCost_ = c;
        _changed("fieldCosts", 0);
    }

    function setUnit(uint8 kind, Unit calldata u, string calldata name) external onlyOwner {
        require(kind < G.UNITS && bytes(name).length <= 32, E.InvalidUnit());
        require(!u.enabled || (u.speed > 0 && u.speed <= 100 && u.room > 0 && u.tier <= MAX_TIERS && u.role <= 2), E.InvalidConfig());
        units_[kind] = u;
        unitNames_[kind] = name;
        _changed("unit", kind);
    }

    function setBuilding(uint8 kind, Building calldata b, string calldata name) external onlyOwner {
        require(kind < G.KINDS && bytes(name).length <= 32, E.InvalidBuilding());
        require(
            b.maxLevel > 0 && b.maxLevel <= 20 && b.thCap <= 2 && b.tier <= MAX_TIERS && b.effect <= G.FX_VAULT
                && b.costGrowth >= 100 && b.timeGrowth >= 100 && (b.seed == 0 || b.seedGrowth >= 100)
                && (kind != G.TH && kind != G.WALLS || b.enabled) && (kind != G.WHEEL || b.maxLevel <= 10)
                && (kind != G.TH || b.maxLevel <= 10),
            E.InvalidConfig()
        );
        buildings_[kind] = b;
        buildingNames_[kind] = name;
        _changed("building", kind);
    }

    function setTier(uint8 tier, Tier calldata t) external onlyOwner {
        require(tier >= 1 && tier <= MAX_TIERS, E.InvalidTier());
        tiers_[tier - 1] = t;
        _changed("tier", tier);
    }

    function setTierCount(uint8 count) external onlyOwner {
        require(count <= MAX_TIERS, E.InvalidTier());
        tierCount = count;
        _changed("tierCount", count);
    }

    // ------------------------------------------------------------------ reads (whole tables)

    function economy() external view returns (Economy memory) { return econ_; }
    function storageRules() external view returns (Storage memory) { return storage_; }
    function war() external view returns (War memory) { return war_; }
    function hero() external view returns (Hero memory) { return hero_; }
    function wild() external view returns (Wild memory) { return wild_; }
    function social() external view returns (Social memory) { return social_; }
    function fieldCosts() external view returns (uint32[4][4] memory) { return fieldCost_; }
    function unit(uint8 kind) external view returns (Unit memory, string memory) { return (units_[kind], unitNames_[kind]); }
    function building(uint8 kind) external view returns (Building memory, string memory) { return (buildings_[kind], buildingNames_[kind]); }
    function tier(uint8 t) external view returns (Tier memory) { return tiers_[t - 1]; }
    function allUnits() external view returns (Unit[16] memory u, string[16] memory names) { return (units_, unitNames_); }
    function allBuildings() external view returns (Building[16] memory b, string[16] memory names) { return (buildings_, buildingNames_); }
    function allTiers() external view returns (Tier[8] memory t, uint8 count) { return (tiers_, tierCount); }

    // ------------------------------------------------------------------ reads used by the game

    function grow(uint256 base, uint256 n, uint256 d, uint256 exponent) public pure returns (uint256) {
        require(exponent <= 20, E.ExponentOutOfBounds());
        for (uint256 i; i < exponent; ++i) {
            base = base * n / d;
        }
        return base;
    }

    function fieldQuote(uint8 field, uint8 level) external view returns (uint256[4] memory cost, uint256 seconds_) {
        Economy storage e = econ_;
        require(field < 8 && level > 0 && level <= e.fieldMaxLevel, E.InvalidField());
        for (uint256 i; i < 4; ++i) {
            cost[i] = grow(uint256(fieldCost_[field / 2][i]) * UNIT, e.fieldCostGrowth, 100, level - 1);
        }
        seconds_ = grow(uint256(e.fieldSeconds) * UNIT, e.fieldTimeGrowth, 100, level - 1) / UNIT;
    }

    function fieldRate(uint8 level) external view returns (uint256) {
        if (level == 0) return 0;
        return grow(uint256(econ_.fieldRate) * UNIT, econ_.fieldRateGrowth, 100, level - 1);
    }

    /// @notice A building slot's level cap, Town Hall cap rule (0 none, 1 ≤ TH, 2 ≤ 2 × TH), tier and switch.
    function buildingRule(uint8 kind) external view returns (uint8 maxLevel, uint8 thCap, uint8 tier_, bool enabled) {
        require(kind < G.KINDS, E.InvalidBuilding());
        Building storage b = buildings_[kind];
        return (b.maxLevel, b.thCap, b.tier, b.enabled);
    }

    function buildingQuote(uint8 kind, uint8 level) external view returns (uint256[4] memory cost, uint256 seed, uint256 seconds_) {
        require(kind < G.KINDS, E.InvalidBuilding());
        Building storage b = buildings_[kind];
        require(level > 0 && level <= b.maxLevel, E.InvalidBuilding());
        for (uint256 i; i < 4; ++i) {
            cost[i] = grow(uint256(b.cost[i]) * UNIT, b.costGrowth, 100, level - 1);
        }
        if (b.seed != 0) seed = grow(uint256(b.seed) * UNIT, b.seedGrowth, 100, level - 1);
        seconds_ = grow(uint256(b.seconds_) * UNIT, b.timeGrowth, 100, level - 1) / UNIT;
    }

    function researchQuote(uint8 t) external view returns (uint256[4] memory cost, uint256 seed, uint256 seconds_, uint8 academy) {
        require(t > 0 && t <= tierCount, E.InvalidTier());
        Tier storage x = tiers_[t - 1];
        for (uint256 i; i < 4; ++i) {
            cost[i] = x.costEachUnit;
        }
        return (cost, x.seedUnit, x.seconds_, x.academy);
    }

    /// @notice Carry and speed bonuses summed over tiers 1..t, and the best medicine among them.
    function tierBonus(uint8 t) external view returns (uint256 carryPct, uint256 speedPct, uint256 medicinePct) {
        for (uint256 i; i < t && i < MAX_TIERS; ++i) {
            Tier storage x = tiers_[i];
            carryPct += x.carryPct;
            speedPct += x.speedPct;
            if (x.medicinePct > medicinePct) medicinePct = x.medicinePct;
        }
        if (medicinePct > 100) medicinePct = 100;
    }

    /// @param kind 0 storage, 1 vault protection (both millionths), 2 troop room (whole)
    function capacity(uint8 kind, uint8 level) external view returns (uint256 total) {
        require(kind < 3, E.InvalidCapacity());
        Storage storage s = storage_;
        total = kind == 0 ? uint256(s.storeBase) * UNIT : kind == 1 ? uint256(s.vaultBase) * UNIT : s.roomBase;
        for (uint256 i = 1; i <= level; ++i) {
            total += kind == 2
                ? grow(uint256(s.roomPer) * i * UNIT, s.roomGrowth, 100, i - 1) / UNIT
                : grow(uint256(kind == 0 ? s.storePer : s.vaultPer) * UNIT, kind == 0 ? s.storeGrowth : s.vaultGrowth, 100, i - 1);
        }
    }

    /// @notice Build time after the Town Hall, the wallet's Squeeks and building effects.
    function buildDuration(uint256 base, uint8 townHall, uint256 nftCount, uint256 work, uint256 cutPct) external view returns (uint256) {
        require(townHall > 0, E.InvalidTownHall());
        Economy storage e = econ_;
        nftCount = G.min(nftCount, NFT_COUNT_PRECISION);
        uint256 workFactor = G.min(work, e.squeekWorkTarget) * UNIT / e.squeekWorkTarget;
        uint256 reduction = uint256(e.squeekBuildPct) * 10_000 * (UNIT - UNIT / (uint256(1) << nftCount)) / UNIT * workFactor / UNIT;
        uint256 th = G.min(90, uint256(e.thBuildCutPct) * (townHall - 1));
        uint256 cut = G.min(90, cutPct);
        return G.ceilDiv(base * (100 - th) * (UNIT - reduction) * (100 - cut), 10_000 * UNIT);
    }

    function unitTable() external view returns (G.UnitTable memory t) {
        for (uint256 i; i < G.UNITS; ++i) {
            Unit storage u = units_[i];
            t.attack[i] = u.attack;
            t.defense[i] = u.defense;
            t.speed[i] = u.speed;
            t.carry[i] = u.carry;
            t.room[i] = u.room;
            t.value[i] = uint256(u.cost[0]) + u.cost[1] + u.cost[2] + u.cost[3];
            t.role[i] = u.role;
        }
    }

    function unitQuote(uint8 kind, uint8 barracks, uint8 researched, uint32 count, uint256 fasterPct)
        external
        view
        returns (uint256[4] memory cost, uint256 duration, uint256 rooms)
    {
        require(kind < G.UNITS && barracks > 0 && count > 0 && count <= MAX_TROOPS, E.InvalidTraining());
        Unit storage u = units_[kind];
        require(u.enabled, E.UnitDisabled());
        require(researched >= u.tier, E.ResearchRequired());
        for (uint256 i; i < 4; ++i) {
            cost[i] = uint256(u.cost[i]) * UNIT * count;
        }
        rooms = uint256(u.room) * count;
        uint256 each = grow(uint256(u.seconds_) * UNIT, econ_.barracksTimePct, 100, G.min(20, barracks - 1));
        duration = G.ceilDiv(each * count * (100 - G.min(90, fasterPct)), 100 * UNIT);
    }

    /// @notice Building effects summed over a village's building levels.
    function mods(uint8[16] calldata levels) external view returns (G.Mods memory m) {
        for (uint256 i; i < G.KINDS; ++i) {
            uint256 l = levels[i];
            if (l == 0) continue;
            Building storage b = buildings_[i];
            uint8 fx = b.effect;
            if (fx == G.FX_NONE || !b.enabled) continue;
            uint256 v = uint256(b.effectPerLevel) * l;
            if (fx == G.FX_DEFENSE_PCT) m.defensePct += v;
            else if (fx == G.FX_ATTACK_PCT) m.attackPct += v;
            else if (fx == G.FX_OUTPUT_PCT) m.outputPct += v;
            else if (fx == G.FX_STORAGE) m.storageAdd += v * UNIT;
            else if (fx == G.FX_ROOM) m.room += v;
            else if (fx == G.FX_TRAIN_PCT) m.trainPct += v;
            else if (fx == G.FX_BUILD_PCT) m.buildPct += v;
            else if (fx == G.FX_CARRY_PCT) m.carryPct += v;
            else if (fx == G.FX_VAULT) m.vault += v * UNIT;
        }
    }
}

SeedLedger.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {GameErrors as E} from "./libraries/GameErrors.sol";

import {ISqueekCore, ISqueekNFT} from "./interfaces/ISqueek.sol";
import {GameTypes as G} from "./libraries/GameTypes.sol";
import {Guard} from "./libraries/Guard.sol";
import {GameConfig} from "./GameConfig.sol";

/// @notice Daily work checkpoints and nontransferable, caller-scoped village balances.
/// @dev The canonical game namespace is the deployed Villages contract. No approvals or transfers exist.
/// The SEED rate, the wheel bonus and the daily XP come from GameConfig; its owner may repoint the reads.
contract SeedLedger is Guard {
    uint256 public constant UNIT = 1_000_000;
    uint256 public constant CORE_READ_GAS = 200_000;
    uint256 public constant NFT_READ_GAS = 100_000;
    GameConfig public immutable config;
    address public core;
    address public squeek;
    uint64 public lastCumulativeWork;

    struct Observation {
        uint64 timestamp;
        uint64 day;
        uint64 work;
        uint256 seedIndex;
        uint256 xpIndex;
        uint256[11] wheelIntegral;
    }

    struct Account {
        bool exists;
        uint256 cursor;
        uint256 balance;
    }
    Observation[] private observations;
    mapping(address game => mapping(address player => Account)) private accounts;
    mapping(address game => uint256) public minted;
    mapping(address game => uint256) public burned;

    error Unauthorized();
    error InvalidAddress();
    error AlreadyCheckpointed();
    error WorkDecreased();
    error ExternalReadFailed();
    error NoClaim();
    error InsufficientSeed();

    event Checkpoint(uint256 indexed index, uint256 indexed day, uint256 work, uint256 cumulativeWork);
    event Registered(address indexed game, address indexed player);
    event Claimed(
        address indexed game, address indexed player, uint256 throughIndex, uint256 seed, uint256 xp
    );
    event Burned(address indexed game, address indexed player, uint256 amount);
    event Refunded(address indexed game, address indexed player, uint256 amount);
    event ReadersChanged(address core, address squeek);

    constructor(GameConfig config_, address core_, address squeek_) {
        if (address(config_) == address(0) || core_ == address(0) || squeek_ == address(0)) revert InvalidAddress();
        config = config_;
        core = core_;
        squeek = squeek_;
    }

    function owner() public view returns (address) {
        return config.owner();
    }

    function dayAt(uint256 timestamp) public pure returns (uint256) {
        return timestamp < 4 hours ? 0 : (timestamp - 4 hours) / 1 days;
    }

    function currentDay() public view returns (uint256) {
        return dayAt(block.timestamp);
    }

    function observationCount() external view returns (uint256) {
        return observations.length;
    }

    function observation(uint256 index) external view returns (Observation memory) {
        return observations[index];
    }

    function balanceOf(address game, address player) external view returns (uint256) {
        return accounts[game][player].balance;
    }

    function account(address game, address player) external view returns (Account memory) {
        return accounts[game][player];
    }

    function lastWork() public view returns (uint256) {
        return observations.length == 0 ? 0 : observations[observations.length - 1].work;
    }

    function _work(address source) private view returns (uint64) {
        (bool ok, bytes memory data) =
            source.staticcall{gas: CORE_READ_GAS}(abi.encodeCall(ISqueekCore.state, ()));
        if (!ok || data.length != 256) revert ExternalReadFailed();
        uint256[8] memory words = abi.decode(data, (uint256[8]));
        if (
            words[0] > type(uint64).max || words[1] > type(uint64).max || words[2] > type(uint96).max
                || words[3] > type(uint64).max || words[4] > type(uint96).max || words[5] > type(uint32).max
                || words[7] > 1
        ) revert ExternalReadFailed();
        return uint64(words[1]);
    }

    function nftBalance(address player) public view returns (uint256) {
        return _nftBalance(squeek, player);
    }

    function _nftBalance(address source, address player) private view returns (uint256) {
        (bool ok, bytes memory data) =
            source.staticcall{gas: NFT_READ_GAS}(abi.encodeCall(ISqueekNFT.balanceOf, (player)));
        if (!ok || data.length != 32) revert ExternalReadFailed();
        return abi.decode(data, (uint256));
    }

    /// @notice First checkpoint establishes a baseline; later ones reward the observed work delta.
    function checkpoint() external nonReentrant {
        _checkpoint();
    }

    function _checkpoint() private {
        uint256 length = observations.length;
        uint256 day = currentDay();
        if (length != 0 && observations[length - 1].day == day) revert AlreadyCheckpointed();
        uint64 current = _work(core);
        if (length != 0 && current < lastCumulativeWork) revert WorkDecreased();
        GameConfig.Economy memory e = config.economy();
        observations.push();
        Observation storage next = observations[length];
        next.timestamp = uint64(block.timestamp);
        next.day = uint64(day);
        if (length != 0) {
            Observation storage previous = observations[length - 1];
            next.work = current - lastCumulativeWork;
            next.seedIndex = previous.seedIndex + uint256(next.work) * UNIT / e.seedWorkDiv;
            next.xpIndex = previous.xpIndex + G.min(e.xpDailyCap, uint256(next.work) / e.xpWorkDiv);
            for (uint8 l = 1; l <= 10; ++l) {
                next.wheelIntegral[l] = previous.wheelIntegral[l] + _bonus(e, previous.work, l)
                    * (block.timestamp - previous.timestamp);
            }
        }
        lastCumulativeWork = current;
        emit Checkpoint(length, day, next.work, current);
    }

    function _bonus(GameConfig.Economy memory e, uint256 work, uint8 level) private pure returns (uint256) {
        return G.min(work * UNIT / e.wheelWorkDiv, uint256(level) * UNIT * e.wheelPctPerLevel / 100);
    }

    /// @notice Time integral of Wheelhouse's fractional output bonus at an arbitrary past time.
    function wheelIntegral(uint8 level, uint256 timestamp) external view returns (uint256) {
        require(level <= 10 && timestamp <= block.timestamp, E.InvalidIntegralQuery());
        uint256 length = observations.length;
        if (length == 0 || level == 0 || timestamp < observations[0].timestamp) return 0;
        uint256 lo;
        uint256 hi = length;
        while (lo + 1 < hi) {
            uint256 mid = (lo + hi) / 2;
            if (observations[mid].timestamp <= timestamp) lo = mid;
            else hi = mid;
        }
        Observation storage o = observations[lo];
        return o.wheelIntegral[level] + _bonus(config.economy(), o.work, level) * (timestamp - o.timestamp);
    }

    function register(address player) external nonReentrant {
        require(
            player != address(0) && !accounts[msg.sender][player].exists, E.AlreadyRegisteredOrInvalidPlayer()
        );
        if (observations.length == 0 || observations[observations.length - 1].day < currentDay()) {
            _checkpoint();
        }
        uint256 start = uint256(config.economy().startSeed) * UNIT;
        accounts[msg.sender][player] = Account(true, observations.length - 1, start);
        minted[msg.sender] += start;
        emit Registered(msg.sender, player);
    }

    function claim(address player) external nonReentrant returns (uint256 seed, uint256 xp) {
        Account storage a = accounts[msg.sender][player];
        uint256 latest = observations.length == 0 ? 0 : observations.length - 1;
        if (!a.exists || a.cursor == latest) revert NoClaim();
        seed = observations[latest].seedIndex - observations[a.cursor].seedIndex;
        xp = observations[latest].xpIndex - observations[a.cursor].xpIndex;
        a.cursor = latest;
        a.balance += seed;
        minted[msg.sender] += seed;
        emit Claimed(msg.sender, player, latest, seed, xp);
    }

    function burn(address player, uint256 amount) external {
        Account storage a = accounts[msg.sender][player];
        if (!a.exists || a.balance < amount) revert InsufficientSeed();
        a.balance -= amount;
        burned[msg.sender] += amount;
        emit Burned(msg.sender, player, amount);
    }

    /// @dev Only refunds previously burned SEED within the caller's own namespace.
    function refund(address player, uint256 amount) external {
        require(accounts[msg.sender][player].exists && amount <= burned[msg.sender], E.InvalidRefund());
        accounts[msg.sender][player].balance += amount;
        burned[msg.sender] -= amount;
        emit Refunded(msg.sender, player, amount);
    }

    /// @notice The config owner points the game at another SqueekCore or Squeek NFT (testnet season).
    /// A different Core is baselined at its current counter, so it never pays out old work.
    function setReaders(address core_, address squeek_) external nonReentrant {
        if (msg.sender != config.owner()) revert Unauthorized();
        if (core_ == address(0) || squeek_ == address(0)) revert InvalidAddress();
        uint64 current = _work(core_);
        if (core_ != core || current < lastCumulativeWork) lastCumulativeWork = current;
        _nftBalance(squeek_, msg.sender);
        core = core_;
        squeek = squeek_;
        emit ReadersChanged(core_, squeek_);
    }
}

Villages.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ModuleCalls} from "./libraries/ModuleCalls.sol";

import {GameErrors as E} from "./libraries/GameErrors.sol";

import {GameTypes as G} from "./libraries/GameTypes.sol";
import {Guard} from "./libraries/Guard.sol";
import {GameConfig} from "./GameConfig.sol";
import {SeedLedger} from "./SeedLedger.sol";
import {Clans} from "./Clans.sol";
import {Army} from "./Army.sol";

/// @notice Canonical player entry point. Every player action derives the village from msg.sender.
/// @dev Every economy number comes from GameConfig at the time of the action.
contract Villages is Guard {
    uint256 public constant UNIT = 1_000_000;
    uint256 public constant VILLAGE_LIMIT = 9800;
    uint256 public constant MAX_MARKET_LOTS = 1_000_000;
    uint256 private constant K = 16;
    GameConfig public immutable config;
    SeedLedger public immutable ledger;
    Clans public immutable clans;
    Army public immutable army;
    uint256 public villageCount;
    uint256 public immutable seasonStartedAt;

    struct Village {
        string name;
        uint16 tile;
        uint64 foundedAt;
        uint64 lastAccrued;
        uint64 shieldUntil;
        uint64 peaceUsedAt;
        uint64 boostUntil;
        uint64 repairAt;
        uint8 boostResource;
        uint8 tier;
        uint8 damagedWalls;
        bool banner;
        uint8[8] fields;
        uint8[16] buildings;
        uint256[4] stock;
        uint256[4] remainder;
        uint256 upkeepRemainder;
    }

    struct BuildOrder {
        uint8 target;
        uint8 level;
        uint64 readyAt;
        uint256[4] cost;
        uint256 seed;
    }

    struct Study {
        uint8 tier;
        uint64 readyAt;
        uint256 spent;
    }
    mapping(address => Village) private villages;
    mapping(address => BuildOrder[2]) private builds;
    mapping(address => Study) private studies;
    mapping(bytes32 => address) public nameOwner;
    mapping(uint16 => address) public tileOwner;

    error NoVillage();
    error OnlyArmy();
    error InvalidAction();
    error NotReady();
    error InsufficientResources();

    event Founded(address indexed player, string name, uint16 tile);
    event Accrued(address indexed player, uint256[4] stock);
    event BuildOrdered(
        address indexed player, uint8 indexed slot, uint8 target, uint8 level, uint256 readyAt
    );
    event BuildCompleted(address indexed player, uint8 indexed slot, uint8 target, uint8 level);
    event BuildCancelled(address indexed player, uint8 indexed slot);
    event ResearchOrdered(address indexed player, uint8 tier, uint256 readyAt);
    event ResearchCompleted(address indexed player, uint8 tier);
    event Exchanged(address indexed player, uint8 input, uint8 output, uint256 lots, uint256 received);
    event TreasuryUsed(address indexed player, uint8 kind, uint8 resource, uint256 until);
    event WallsDamaged(address indexed player, uint8 remainingDamage, uint256 nextRepair);

    constructor(GameConfig config_, SeedLedger ledger_, Clans clans_, Army army_) {
        require(
            address(config_) != address(0) && address(ledger_) != address(0) && address(clans_) != address(0)
                && address(army_) != address(0),
            E.InvalidDependency()
        );
        config = config_;
        ledger = ledger_;
        clans = clans_;
        army = army_;
        seasonStartedAt = block.timestamp;
    }
    modifier player() {
        if (villages[msg.sender].foundedAt == 0) revert NoVillage();
        _;
    }
    modifier onlyArmy() {
        if (msg.sender != address(army)) revert OnlyArmy();
        _;
    }

    function village(address who) external view returns (Village memory) {
        return villages[who];
    }

    function buildOrder(address who, uint8 slot) external view returns (BuildOrder memory) {
        require(slot < 2, E.InvalidSlot());
        return builds[who][slot];
    }

    function study(address who) external view returns (Study memory) {
        return studies[who];
    }

    function seedBalance(address who) external view returns (uint256) {
        return abi.decode(
            ModuleCalls.read(address(ledger), abi.encodeCall(ledger.balanceOf, (address(this), who)), 32),
            (uint256)
        );
    }

    /// @notice Map slot of the n-th village: 48 villages, then a camp slot, for the first 200 camps.
    function villageSlot(uint256 n) public pure returns (uint256) {
        return n + G.min(n / 48, 200);
    }

    function tileForSlot(uint256 slot) external pure returns (uint16) {
        require(slot < 10000, E.InvalidSlot());
        return G.tile(slot);
    }

    function campTile(uint256 campId) external pure returns (uint16) {
        require(campId < 200, E.InvalidCamp());
        return G.tile(campId * 49 + 48);
    }

    function found(string calldata name) external nonReentrant {
        if (villages[msg.sender].foundedAt != 0 || villageCount >= VILLAGE_LIMIT) revert InvalidAction();
        bytes32 key = G.nameKey(name, 16);
        require(nameOwner[key] == address(0), E.NameTaken());
        GameConfig.Economy memory e = config.economy();
        uint16 tile = G.tile(villageSlot(villageCount));
        Village storage v = villages[msg.sender];
        v.name = name;
        v.tile = tile;
        v.foundedAt = uint64(block.timestamp);
        v.lastAccrued = uint64(block.timestamp);
        v.shieldUntil = uint64(block.timestamp + uint256(e.shieldHours) * 1 hours);
        v.buildings[G.TH] = 1;
        v.buildings[G.WALLS] = 1;
        for (uint256 i; i < 8; ++i) {
            v.fields[i] = 1;
        }
        for (uint256 i; i < 4; ++i) {
            v.stock[i] = uint256(e.startResources) * UNIT;
        }
        nameOwner[key] = msg.sender;
        tileOwner[tile] = msg.sender;
        ++villageCount;
        ModuleCalls.invoke(address(ledger), abi.encodeCall(ledger.register, (msg.sender)), 0);
        emit Founded(msg.sender, name, tile);
    }

    function claimSeed() external player nonReentrant returns (uint256 seed, uint256 xp) {
        (seed, xp) = abi.decode(
            ModuleCalls.invoke(address(ledger), abi.encodeCall(ledger.claim, (msg.sender)), 64),
            (uint256, uint256)
        );
        ModuleCalls.invoke(address(army), abi.encodeCall(army.creditXP, (msg.sender, xp)), 0);
    }

    function sync(address who) external nonReentrant {
        _accrue(who);
    }

    function modsOf(address who) public view returns (G.Mods memory) {
        return config.mods(villages[who].buildings);
    }

    function storageCapacity(address who) public view returns (uint256) {
        return config.capacity(0, villages[who].buildings[G.STORE]) + modsOf(who).storageAdd;
    }

    function vaultProtection(address who) public view returns (uint256) {
        return config.capacity(1, villages[who].buildings[G.VAULT]) + modsOf(who).vault;
    }

    function roomCapacity(address who) public view returns (uint256) {
        return config.capacity(2, villages[who].buildings[G.BURROW]) + modsOf(who).room;
    }

    function stock(address who) external view returns (uint256[4] memory amounts) {
        (amounts,,) = _production(who);
    }

    function _production(address who)
        private
        view
        returns (uint256[4] memory amounts, uint256[4] memory remainder, uint256 upkeepRemainder)
    {
        Village storage v = villages[who];
        if (v.foundedAt == 0) revert NoVillage();
        amounts = v.stock;
        remainder = v.remainder;
        upkeepRemainder = v.upkeepRemainder;
        uint256 elapsed = block.timestamp - v.lastAccrued;
        if (elapsed == 0) return (amounts, remainder, upkeepRemainder);
        GameConfig.Economy memory e = config.economy();
        uint256 integralStart = _wheelIntegral(v.buildings[G.WHEEL], v.lastAccrued);
        uint256 weighted =
            elapsed * UNIT + _wheelIntegral(v.buildings[G.WHEEL], block.timestamp) - integralStart;
        uint256 boosted;
        if (v.boostUntil > v.lastAccrued) {
            uint256 end = G.min(block.timestamp, v.boostUntil);
            boosted = (end - v.lastAccrued) * UNIT + _wheelIntegral(v.buildings[G.WHEEL], end) - integralStart;
        }
        uint256 cap = storageCapacity(who);
        uint256 output = 100 + modsOf(who).outputPct;
        for (uint8 i; i < 4; ++i) {
            uint256 rate = config.fieldRate(v.fields[i * 2]) + config.fieldRate(v.fields[i * 2 + 1]);
            uint256 numerator =
                rate * (weighted * output + (i == v.boostResource ? boosted * e.boostPct : 0)) + remainder[i];
            amounts[i] += numerator / (360_000 * UNIT);
            remainder[i] = numerator % (360_000 * UNIT);
        }
        uint256 upkeep = elapsed
            * abi.decode(
                ModuleCalls.read(address(army), abi.encodeCall(army.allocatedRoom, (address(this), who)), 32),
                (uint256)
            ) * UNIT * e.upkeepMilli + upkeepRemainder;
        uint256 foodCost = upkeep / 3_600_000;
        upkeepRemainder = upkeep % 3_600_000;
        amounts[1] = amounts[1] > foodCost ? amounts[1] - foodCost : 0;
        if (amounts[1] == 0) upkeepRemainder = 0;
        for (uint8 i; i < 4; ++i) {
            if (amounts[i] >= cap) {
                amounts[i] = cap;
                remainder[i] = 0;
            }
        }
    }

    function _accrue(address who) private {
        Village storage v = villages[who];
        (v.stock, v.remainder, v.upkeepRemainder) = _production(who);
        v.lastAccrued = uint64(block.timestamp);
        emit Accrued(who, v.stock);
    }

    function _spend(address who, uint256[4] memory cost) private {
        Village storage v = villages[who];
        for (uint8 i; i < 4; ++i) {
            if (v.stock[i] < cost[i]) revert InsufficientResources();
            v.stock[i] -= cost[i];
        }
    }

    function _credit(address who, uint256[4] memory amounts) private {
        uint256 cap = storageCapacity(who);
        for (uint8 i; i < 4; ++i) {
            villages[who].stock[i] = G.min(cap, villages[who].stock[i] + amounts[i]);
        }
    }

    function _spent(uint256[4] memory amounts, uint256 seed) private pure returns (uint256) {
        return amounts[0] + amounts[1] + amounts[2] + amounts[3] + seed;
    }

    /// @notice Targets 0..7 are fields; 8..23 are building slots 0..15.
    function orderBuild(uint8 target, uint8 slot) external player nonReentrant {
        require(target < 8 + K && slot < 2 && builds[msg.sender][slot].readyAt == 0, E.InvalidBuildSlot());
        for (uint8 i; i < 2; ++i) {
            require(
                builds[msg.sender][i].readyAt == 0 || builds[msg.sender][i].target != target,
                E.AlreadyBuildingTarget()
            );
        }
        Village storage v = villages[msg.sender];
        GameConfig.Economy memory e = config.economy();
        uint8 level;
        uint256[4] memory cost;
        uint256 seed;
        uint256 duration;
        if (target < 8) {
            level = v.fields[target] + 1;
            require(level <= e.fieldMaxLevel && level <= v.buildings[G.TH], E.FieldCappedByTownHall());
            (cost, duration) = config.fieldQuote(target, level);
        } else {
            uint8 kind = target - 8;
            level = v.buildings[kind] + 1;
            (uint8 maxLevel, uint8 thCap, uint8 tierNeeded, bool enabled) = config.buildingRule(kind);
            require(enabled, E.BuildingDisabled());
            require(level <= maxLevel, E.MaxLevel());
            if (thCap != 0) require(level <= uint256(v.buildings[G.TH]) * thCap, E.BuildingCappedByTownHall());
            if (v.tier < tierNeeded) revert E.ResearchRequired();
            if (level == 1) {
                uint256 plots;
                for (uint8 i; i < K; ++i) {
                    if (v.buildings[i] != 0) ++plots;
                }
                for (uint8 i; i < 2; ++i) {
                    if (
                        builds[msg.sender][i].readyAt != 0 && builds[msg.sender][i].target >= 8
                            && builds[msg.sender][i].level == 1
                    ) ++plots;
                }
                require(plots < G.min(e.plotsMax, uint256(e.plotsBase) + v.buildings[G.TH]), E.NoPlotAvailable());
            }
            (cost, seed, duration) = config.buildingQuote(kind, level);
        }
        duration = config.buildDuration(
            duration,
            v.buildings[G.TH],
            abi.decode(ModuleCalls.read(address(ledger), abi.encodeCall(ledger.nftBalance, (msg.sender)), 32), (uint256)),
            abi.decode(ModuleCalls.read(address(ledger), abi.encodeCall(ledger.lastWork, ()), 32), (uint256)),
            modsOf(msg.sender).buildPct
        );
        _accrue(msg.sender);
        _spend(msg.sender, cost);
        if (seed != 0) _burn(seed);
        builds[msg.sender][slot] = BuildOrder(target, level, uint64(block.timestamp + duration), cost, seed);
        emit BuildOrdered(msg.sender, slot, target, level, block.timestamp + duration);
    }

    function completeBuild(address who, uint8 slot) external nonReentrant {
        require(slot < 2, E.InvalidSlot());
        BuildOrder memory b = builds[who][slot];
        if (b.readyAt == 0 || block.timestamp < b.readyAt) revert NotReady();
        _accrue(who);
        delete builds[who][slot];
        if (b.target < 8) villages[who].fields[b.target] = b.level;
        else villages[who].buildings[b.target - 8] = b.level;
        ModuleCalls.invoke(address(clans), abi.encodeCall(clans.record, (who, 0, _spent(b.cost, b.seed))), 0);
        emit BuildCompleted(who, slot, b.target, b.level);
    }

    function cancelBuild(uint8 slot) external player nonReentrant {
        require(slot < 2, E.InvalidSlot());
        BuildOrder memory b = builds[msg.sender][slot];
        require(b.readyAt != 0 && block.timestamp < b.readyAt, E.CannotCancelCompletedBuild());
        delete builds[msg.sender][slot];
        _accrue(msg.sender);
        uint256 pct = config.economy().cancelRefundPct;
        for (uint8 i; i < 4; ++i) {
            b.cost[i] = b.cost[i] * pct / 100;
        }
        _credit(msg.sender, b.cost);
        if (b.seed != 0 && pct != 0) {
            ModuleCalls.invoke(
                address(ledger), abi.encodeCall(ledger.refund, (msg.sender, b.seed * pct / 100)), 0
            );
        }
        emit BuildCancelled(msg.sender, slot);
    }

    function orderResearch() external player nonReentrant {
        Village storage v = villages[msg.sender];
        require(studies[msg.sender].readyAt == 0, E.ResearchBusy());
        uint8 tier = v.tier + 1;
        (uint256[4] memory cost, uint256 seed, uint256 duration, uint8 academy) = config.researchQuote(tier);
        require(v.buildings[G.ACADEMY] >= academy, E.AcademyTooLow());
        _accrue(msg.sender);
        _spend(msg.sender, cost);
        if (seed != 0) _burn(seed);
        studies[msg.sender] = Study(tier, uint64(block.timestamp + duration), _spent(cost, seed));
        emit ResearchOrdered(msg.sender, tier, block.timestamp + duration);
    }

    function completeResearch(address who) external nonReentrant {
        Study memory s = studies[who];
        if (s.readyAt == 0 || block.timestamp < s.readyAt) revert NotReady();
        delete studies[who];
        villages[who].tier = s.tier;
        ModuleCalls.invoke(address(clans), abi.encodeCall(clans.record, (who, 1, s.spent)), 0);
        emit ResearchCompleted(who, s.tier);
    }

    /// @notice Input 0..3 is a resource, 4 is SEED; output is always a different resource.
    function exchange(uint8 input, uint8 output, uint256 lots) external player nonReentrant {
        require(
            input < 5 && output < 4 && input != output && lots > 0 && lots <= MAX_MARKET_LOTS,
            E.InvalidExchange()
        );
        Village storage v = villages[msg.sender];
        uint8 market = v.buildings[G.MARKET];
        require(market != 0, E.MarketRequired());
        _accrue(msg.sender);
        uint256 paid = lots * 100 * UNIT;
        if (input == 4) {
            _burn(paid);
        } else {
            if (v.stock[input] < paid) revert InsufficientResources();
            v.stock[input] -= paid;
        }
        GameConfig.Economy memory e = config.economy();
        uint256 received = lots * (uint256(e.marketBase) + uint256(e.marketPerLevel) * (market - 1)) * UNIT;
        require(v.stock[output] + received <= storageCapacity(msg.sender), E.InsufficientStorage());
        v.stock[output] += received;
        emit Exchanged(msg.sender, input, output, lots, received);
    }

    /// @notice Kind 0: resource boost; 1: peace shield; 2: permanent decorative banner.
    function treasury(uint8 kind, uint8 resource) external player nonReentrant {
        Village storage v = villages[msg.sender];
        GameConfig.Economy memory e = config.economy();
        uint256 until;
        if (kind == 0) {
            require(resource < 4 && block.timestamp >= v.boostUntil, E.BoostActiveOrInvalidResource());
            _accrue(msg.sender);
            _burn(uint256(e.boostSeed) * UNIT);
            v.boostResource = resource;
            until = block.timestamp + uint256(e.boostHours) * 1 hours;
            v.boostUntil = uint64(until);
        } else if (kind == 1) {
            require(
                v.peaceUsedAt == 0 || block.timestamp >= v.peaceUsedAt + uint256(e.peaceCooldownHours) * 1 hours,
                E.PeaceCooldown()
            );
            until = block.timestamp + uint256(e.peaceHours) * 1 hours;
            require(v.shieldUntil < until, E.ShieldAlreadyActive());
            _burn(uint256(e.peaceSeed) * UNIT);
            v.peaceUsedAt = uint64(block.timestamp);
            v.shieldUntil = uint64(until);
        } else if (kind == 2) {
            require(!v.banner, E.BannerAlreadyOwned());
            _burn(uint256(e.bannerSeed) * UNIT);
            v.banner = true;
        } else {
            revert InvalidAction();
        }
        emit TreasuryUsed(msg.sender, kind, resource, until);
    }

    function foundClan(string calldata name) external player nonReentrant returns (uint256) {
        return abi.decode(
            ModuleCalls.invoke(
                address(clans),
                abi.encodeCall(clans.found, (msg.sender, name, villages[msg.sender].buildings[G.CLAN])),
                32
            ),
            (uint256)
        );
    }

    function joinClan(uint256 id) external player nonReentrant {
        ModuleCalls.invoke(
            address(clans),
            abi.encodeCall(clans.join, (msg.sender, id, villages[msg.sender].buildings[G.CLAN])),
            0
        );
    }

    function inviteToClan(address who, bool open) external player nonReentrant {
        ModuleCalls.invoke(address(clans), abi.encodeCall(clans.invite, (msg.sender, who, open)), 0);
    }

    function leaveClan() external player nonReentrant {
        ModuleCalls.invoke(address(clans), abi.encodeCall(clans.leave, (msg.sender)), 0);
    }

    function raiseClanCapacity() external player nonReentrant {
        ModuleCalls.invoke(
            address(clans),
            abi.encodeCall(clans.raiseCapacity, (msg.sender, villages[msg.sender].buildings[G.CLAN])),
            0
        );
    }

    function train(uint8 kind, uint32 count) external player nonReentrant {
        ModuleCalls.invoke(address(army), abi.encodeCall(army.train, (msg.sender, kind, count)), 0);
    }

    function allocateChampion(uint8 might, uint8 attack, uint8 defense, uint8 carry)
        external
        player
        nonReentrant
    {
        ModuleCalls.invoke(
            address(army), abi.encodeCall(army.allocate, (msg.sender, might, attack, defense, carry)), 0
        );
    }

    /// @notice Modes: 1 raid, 2 scout, 3 support. campId is used only when target is zero.
    function send(address target, uint16 campId, uint32[16] calldata units, bool champion, uint8 mode)
        external
        player
        nonReentrant
        returns (uint256)
    {
        uint256 id = abi.decode(
            ModuleCalls.invoke(
                address(army),
                abi.encodeCall(army.send, (msg.sender, target, campId, units, champion, mode)),
                32
            ),
            (uint256)
        );
        if (mode == 1 || mode == 2) villages[msg.sender].shieldUntil = uint64(block.timestamp);
        return id;
    }

    function recall(uint256 movement) external player nonReentrant {
        ModuleCalls.invoke(address(army), abi.encodeCall(army.recall, (msg.sender, movement)), 0);
    }

    function effectiveWalls(address who) public view returns (uint8) {
        Village storage v = villages[who];
        uint256 damage = v.damagedWalls;
        if (damage != 0 && block.timestamp >= v.repairAt) {
            uint256 repaired = 1 + (block.timestamp - v.repairAt) / (uint256(config.war().repairHours) * 1 hours);
            damage = damage > repaired ? damage - repaired : 0;
        }
        return uint8(v.buildings[G.WALLS] - damage);
    }

    function armyContext(address who) external view returns (G.Context memory) {
        Village storage v = villages[who];
        G.Mods memory m = modsOf(who);
        return G.Context(
            v.foundedAt != 0,
            v.tile,
            v.buildings[G.TH],
            effectiveWalls(who),
            v.buildings[G.FORGE],
            v.buildings[G.BARRACKS],
            v.tier,
            roomCapacity(who),
            v.shieldUntil,
            uint16(G.min(m.attackPct, 1000)),
            uint16(G.min(m.defensePct, 1000)),
            uint16(G.min(m.carryPct, 1000)),
            uint16(G.min(m.trainPct, 90))
        );
    }

    function armyTouch(address who) external onlyArmy {
        _accrue(who);
    }

    function armySpend(address who, uint256[4] calldata cost) external onlyArmy {
        _accrue(who);
        _spend(who, cost);
    }

    function armyCredit(address who, uint256[4] calldata amounts) external onlyArmy {
        _accrue(who);
        _credit(who, amounts);
    }

    function armyRecord(address who, uint8 kind, uint256 amount) external onlyArmy {
        ModuleCalls.invoke(address(clans), abi.encodeCall(clans.record, (who, kind, amount)), 0);
    }

    function armyLoot(address who, uint256 capacity) external onlyArmy returns (uint256[4] memory taken) {
        _accrue(who);
        uint256 guard = vaultProtection(who);
        for (uint8 i; i < 4; ++i) {
            uint256 available = villages[who].stock[i] > guard ? villages[who].stock[i] - guard : 0;
            taken[i] = G.min(capacity / 4, available);
            villages[who].stock[i] -= taken[i];
        }
    }

    function armyDamageWalls(address who, uint8 damage) external onlyArmy {
        Village storage v = villages[who];
        uint256 step = uint256(config.war().repairHours) * 1 hours;
        uint8 oldDamage = v.damagedWalls;
        uint8 currentDamage = v.buildings[G.WALLS] - effectiveWalls(who);
        if (currentDamage == 0) {
            v.repairAt = uint64(block.timestamp + step);
        } else if (oldDamage != currentDamage) {
            v.repairAt += uint64(uint256(oldDamage - currentDamage) * step);
        }
        v.damagedWalls = uint8(G.min(v.buildings[G.WALLS], uint256(currentDamage) + damage));
        emit WallsDamaged(who, v.damagedWalls, v.repairAt);
    }

    function _wheelIntegral(uint8 level, uint256 timestamp) private view returns (uint256) {
        return abi.decode(
            ModuleCalls.read(address(ledger), abi.encodeCall(ledger.wheelIntegral, (level, timestamp)), 32),
            (uint256)
        );
    }

    function _burn(uint256 amount) private {
        ModuleCalls.invoke(address(ledger), abi.encodeCall(ledger.burn, (msg.sender, amount)), 0);
    }
}

